    "z-t5": { q: "Op hoeveel vakantiedagen heb je in Duitsland wettelijk minstens recht bij een 5-daagse werkweek?", o: ["15 dagen", "20 dagen", "25 dagen", "30 dagen"],
      title: "Laat je vakantiedagen niet vervallen", text: "De wet noemt 24 werkdagen bij een 6-daagse week, dat zijn 20 dagen bij een 5-daagse week. Meegenomen dagen moeten meestal uiterlijk 31 maart zijn opgenomen.",
      src: "Duitse federale vakantiewet, § 3 en § 7", ask: "Voeg je vrije dagen toe, dan gaat er niets verloren." },
    "z-g6": { q: "Hoe lang geldt in Duitsland de wettelijke garantie op nieuwe producten?", o: ["6 maanden", "1 jaar", "2 jaar", "5 jaar"],
      title: "Bewaar je kassabon", text: "De 2 jaar lopen vanaf de levering van het product. Bewaar de kassabon of factuur goed. Een fabrieksgarantie is iets anders: die geeft de fabrikant of winkel vrijwillig.",
      src: "Duits Burgerlijk Wetboek, § 438", ask: "Nieuw apparaat gekocht? Noteer wanneer de 2 jaar eindigen." },
